window.docContents[237].resolve({"/Preface/#Preface":{"contents":"The SF course at Penn (CIS 5000) sometimes attracts\nstudents who don't have enough math background and begin really\nflailing around the middle of the semester. I wonder if we could\nhelp these people weed themselves out by offering some kind of more\ndetailed self-assessment near the beginning, maybe in this\nchapter.Some concepts that I would hope people have seen before:* recursive, polymorphic functional programming over lists* abstract definitions involving relations (e.g., reflexive,\n    symmetric, transitive closure of a relation)\n\n\n\n\n\n\n\n\n\n\n\n","context":"Logical Foundations","header":"1. Preface","id":"/Preface/#Preface"}});